UPDATE products
SET title = (
      SELECT products.brand || ' ' || catalog.feature || ' ' || CASE ((CAST(substr(products.product_id,-4) AS INTEGER)-1) % 6) WHEN 0 THEN '基础款' WHEN 1 THEN '大容量款' WHEN 2 THEN '轻量款' WHEN 3 THEN '专业款' WHEN 4 THEN '易维护款' ELSE '历史款' END
      FROM catalog WHERE catalog.n=CAST((CAST(substr(products.product_id,-4) AS INTEGER)+5)/6 AS INTEGER)
    ),
    description = (
      SELECT catalog.feature || '属于' || products.category || '目录；' || catalog.verification_fact || '；' || CASE ((CAST(substr(products.product_id,-4) AS INTEGER)-1) % 6) WHEN 0 THEN '基础款重点核对尺寸与退换条件。' WHEN 1 THEN '大容量款重点核对收纳和持续使用。' WHEN 2 THEN '轻量款重点核对承载与耐久。' WHEN 3 THEN '专业款重点核对兼容与安装。' WHEN 4 THEN '易维护款重点核对清洁和耗材。' ELSE '历史款用于比较旧价格与当前保修差异。' END
      FROM catalog WHERE catalog.n=CAST((CAST(substr(products.product_id,-4) AS INTEGER)+5)/6 AS INTEGER)
    )
WHERE product_id GLOB 'dpf_hhigh_[0-9][0-9][0-9][0-9]';

