UPDATE skus
SET attrs_json = (
  SELECT json_object('catalog_feature',catalog.feature,'verification',catalog.verification_fact,'package_profile',CASE ((CAST(substr(skus.sku_id,-4) AS INTEGER)-1) % 6) WHEN 0 THEN 'basic' WHEN 1 THEN 'capacity' WHEN 2 THEN 'lightweight' WHEN 3 THEN 'professional' WHEN 4 THEN 'serviceable' ELSE 'historical' END)
  FROM catalog WHERE catalog.n=CAST((CAST(substr(skus.sku_id,-4) AS INTEGER)+5)/6 AS INTEGER)
)
WHERE sku_id GLOB 'dsk_hhigh_[0-9][0-9][0-9][0-9]';
COMMIT;
